def solve():
	n = int(input())
	T = [[] for _ in range(n)]
	for i in range(n - 1):
		(u, v) = [int(x) - 1 for x in input().split()]
		T[u].append((v, i))
		T[v].append((u, i))
	start = None
	for (idx, edges) in enumerate(T):
		if len(edges) > 2:
			return '-1'
		if len(edges) == 1:
			start = idx
	ret = [None] * (n - 1)
	val = 2
	p = start
	parent = -1
	while True:
		found = False
		for (q, idx) in T[p]:
			if q != parent:
				found = True
				ret[idx] = val
				parent = p
				p = q
				break
		val = 2 if val == 3 else 3
		if not found:
			break
	return ' '.join([str(x) for x in ret])
t = int(input())
for _ in range(t):
	print(solve())
